  "dashboard.downloadAllServerTitle": "Salvează toate proiectele de pe server, cu dosarele lor, într-un singur fișier ZIP – „Restaurează copia” le aduce într-un browser, chiar și pe alt calculator",
  "dashboard.dragHintServerTab": "Trage peste un dosar sau peste fila Server ca să muți proiectul acolo",
  "storageNotice.line": "Aceste proiecte sunt stocate doar în acest browser. O eroare sau o actualizare a browserului le poate șterge. Folosește „{button}” de mai sus ca să le salvezi pe toate într-un singur fișier.",
  "welcome.hide": "Ascunde ghidul de bun venit – un link din subsol îl aduce înapoi",
  "dashboard.newOnServer": "Proiecte noi pe server",
  "dashboard.newOnServerTitle": "Proiectele noi pornesc în dosarul de pe server, așa că se salvează acolo de la prima modificare. Proiectele din acest browser rămân cum sunt.",
  "dashboard.newOnServerLockedTitle": "Setat de server: orice proiect nou pornește în dosarul de pe server.",
