  "shortcuts.group.help": "Ajutor",
  "shortcuts.commandSearch": "Deschide căutarea de comenzi",
  "interactiveHelp.title": "Ajutor interactiv",
  "interactiveHelp.subtitle": "Dă clic pe orice ca să afli despre el",
  "interactiveHelp.named": "„{name}”",
  "interactiveHelp.close": "Închide fereastra de ajutor",
  "interactiveHelp.nothing": "Nu e nimic de explicat aici. Indică un buton, un câmp, un mâner sau o fereastră.",
  "interactiveHelp.loading": "Caut în ghid ...",
  "interactiveHelp.noIndex": "Ghidul nu este încă disponibil aici. Deschide-l din panoul de proiecte.",
  "interactiveHelp.panelOnly": "Această parte nu are un nume propriu. Semnul întrebării din fereastra ei deschide partea din ghid despre ea.",
