  "interactiveHelp.also": "Și în ghid",
  "interactiveHelp.search": "Caută în ghid",
  "interactiveHelp.open": "Deschide în ghid",
  "interactiveHelp.started": "Ajutorul interactiv e pornit: dă clic pe un buton, un câmp sau o fereastră ca să afli despre ele. Esc iese.",
  "interactiveHelp.ended": "Ajutorul interactiv e oprit",
  "shortcuts.interactiveHelp": "Pornește sau oprește ajutorul interactiv",
  "installHint.chromium": "Instalează-l cu iconița din dreapta barei de adrese sau din meniul browserului, la „Instalează ca aplicație”.",
  "installHint.safariMac": "În Safari: meniul Fișier → „Adaugă în Dock”.",
  "installHint.ios": "În Safari: iconița Partajare → „Adaugă pe ecranul principal”.",
  "installHint.firefox": "Firefox nu poate instala aplicații – Magic3D pornește totuși offline aici, în filă.",
  "welcome.moreLanguagesTitle": "Limba ta",
  "welcome.moreLanguagesBody": "programul și ghidul vorbesc engleză, germană și încă 17 limbi; lista de limbi e chiar în dreapta sus și în setările de pe pagina de start.",
  "welcome.moreOfflineTitle": "Funcționează offline",
  "welcome.moreOfflineBody": "după prima vizită, Magic3D pornește și fără internet – instalează-l ca pe un program obișnuit, iar proiectele tale rămân pe calculatorul tău.",
  "welcome.moreAiTitle": "Construiește cu AI",
  "welcome.moreAiBody": "prin interfața MCP, un asistent AI poate crea și edita forme, într-un editor pe care îl deschide singur. E nevoie de o copie rulată de tine (npm run dev sau imaginea Docker); pe magic3d.ro conexiunea AI e oprită.",
  "welcome.morePointsTitle": "Puncte de referință",
  "welcome.moreSearchTitle": "Căutare comenzi",
  "welcome.moreSimplifyTitle": "Simplificare mesh-uri",
  "welcome.moreSimplifyBody": "Un mesh importat cu un număr foarte mare de triunghiuri e redus la o fracțiune, cu o vedere înainte și după și un glisor – ca tăierea, gruparea și tragerea să rămână fluide.",
  "welcome.moreHistoryTitle": "Istoric",
  "welcome.moreLookTitle": "Aspect după gustul tău",
  "welcome.moreLookBody": "Fundalul și planul de lucru, săgețile axelor X, Y și Z, liniile de muchie pe fiecare corp, culorile schiței, contrastul, umbrele și direcția luminii le setezi tu în setări – de exemplu, ca să nu se contopească corpurile întunecate. Pe calculatoarele mai lente, modul rapid oprește dintr-odată tot ce consumă mult.",
  "welcome.moreControlsTitle": "Mouse și mouse 3D",
  "welcome.moreControlsBody": "face, dacă vrei, ca butoanele mouse-ului să funcționeze ca în Bambu Studio și OrcaSlicer – tragerea cu butonul stâng pe un spațiu gol rotește vederea, butonul drept o deplasează – și controlează vederea cu un SpaceMouse în Chrome și Edge.",
  "welcome.moreTabletTitle": "Pe tabletă",
  "welcome.moreTabletBody": "un deget lucrează pe proiect ca butonul stâng al mouse-ului, două degete fac zoom și deplasează vederea; o tastatură Bluetooth aduce scurtăturile.",
  "welcome.moreHistoryBody": "revezi orice stare anterioară a proiectului cu un glisor, fără să schimbi nimic – exportă acea stare, pornește un proiect nou din ea sau adu înapoi obiecte individuale din ea. Anulează și Refă numesc pasul pe care îl iau înapoi, cu măsura lui, iar o listă numește fiecare pas la care poți sări.",
  "welcome.moreDrawingTitle": "Desen pentru atelier",
  "welcome.moreDrawingBody": "Export → Desen: vederi din față, de sus și din lateral la scara 1:1 pe o foaie ISO, cu dimensiuni de gabarit, muchii ascunse și un tabel al alezajelor rotunde – ca PDF sau SVG, de printat sau de dus la strung și la freză. Vederea de sus ca SVG sau DXF merge la tăierea laser, cu punți de șablon care țin mijlocul unui o sau b, dacă vrei.",
  "welcome.moreSearchBody": "Apasă Ctrl+K și tastează numele unei unelte, al unei forme sau al unei comenzi ca să sari direct la ea – în engleză sau germană, cu scurtăturile de tastatură afișate lângă fiecare. Corpurile din proiectul tău se găsesc și ele după nume.",
  "welcome.moreHelpTitle": "Ajutor interactiv",
  "welcome.moreHelpBody": "apasă Shift+F1 sau semnul întrebării, apoi dă clic pe orice buton, câmp sau fereastră: o fereastră mică arată partea din ghid despre el.",
  "welcome.morePointsBody": "dă clic dreapta pe un corp ca să-i marchezi centrul, colțurile sau mijloacele muchiilor cu puncte care nu se printează și la care se aliniază formele – apoi pune o gaură exact în centrul altei piese.",
  "welcome.videosTitle": "Videoclipuri despre Magic3D",
  "welcome.videosHint": "Făcute de alții, nu de acest proiect. Linkurile deschid YouTube într-o filă nouă; nu se încarcă nimic de acolo până nu dai clic.",
  "welcome.help": "În editor, grupul Ajutor conține un ghid scurt și lista tuturor scurtăturilor de tastatură. În subsol, „Raportează o eroare” salvează proiectul cu tot ce e necesar pentru un raport pe forum sau pe GitHub.",
  "welcome.guideLink": "Citește ghidul complet al utilizatorului, cu imagini",
  "welcome.guideUrl": "/guide/index.html",
