  "shell.errorRoundedEdges": "Această cutie are muchiile de sus și de jos rotunjite, iar peretele trebuie să fie clar mai subțire decât rotunjirea. Alege un perete mai subțire sau setează rotunjirea muchiilor de sus și de jos la 0 înainte de golire. Dacă tot nu merge, „Raport de eroare” din bara de jos salvează proiectul pentru un raport.",
  "shell.errorCannotHollow": "Acest corp nu poate fi golit, nici măcar cu un perete foarte subțire. Probabil conturul lui nu e destul de curat pentru nucleul CAD; o decupare care atinge muchia exterioară, cum ar fi o ușă tăiată până la marginea de jos a unei forme importate, poate cauza asta.",
  "shell.errorNoFlatTop": "Acest corp nu are sus o față plată care să rămână deschisă. Sferele și formele libere nu pot fi golite așa.",
  "shell.errorNoFlatBottom": "Acest corp nu are jos o față plată care să rămână deschisă.",
  "edge.errorOldRevolve": "Acest corp de revoluție a fost construit ca mesh de o versiune mai veche de Magic3D. Deschide Editează schița și finalizeaz-o din nou ca să devină un corp exact; apoi poate fi golit, rotunjit și teșit.",
  "shell.errorNoFlatSide": "Acest corp nu are pe partea aleasă o față plată care să rămână deschisă.",
  "shell.errorProjectChanged": "Obiectul sau proiectul s-a schimbat în timpul golirii; încearcă din nou.",
  "shell.errorFailed": "Corpul nu a putut fi golit. Alege altă grosime a peretelui sau altă deschidere.",
  "status.shelled": "Golit cu pereți de {size} mm",
  "status.shelledClosed": "Golit cu pereți de {size} mm, închis peste tot: cavitatea e în interior și se vede doar în vederea în secțiune",
  "status.shelledMcp": "MCP a golit obiectul cu pereți de {size} mm",
  "status.shellRebuilt": "Pereți recalculați, din nou de {size} mm grosime",
  "status.shellRebuildFailed": "Golirea nu a putut fi recalculată la această mărime. Pereții au fost scalați odată cu corpul.",
  "status.sketchRebuildFailed": "Corpul schiței nu a putut fi reconstruit la această mărime. Teșitura și rotunjirea vor funcționa din nou pe el după ce editezi schița.",
  "edge.revertShell": "Golire (pereți de {size} mm)",
  "editor.tool.cutOut": "Decupează",
  "cutOut.title": "Decupează un corp din altul",
  "cutOut.subtitle": "Piesa rămâne, celălalt corp primește forma ei ca o cavitate",
  "cutOut.help": "Scade o copie a piesei din celălalt corp, ca cele două să se potrivească. Piesa însăși rămâne neschimbată.",
