  "cutOut.clearanceHint": "Cu cât e mai mare cavitatea decât piesa pe fiecare parte. 0 o face să se potrivească exact; 0,2 mm e un joc obișnuit pentru o îmbinare printată.",
  "cutOut.apply": "Decupează",
