  "editor.tool.offset": "Decalare",
  "offset.title": "Decalează corpul",
  "offset.subtitle": "Fiecare față mutată cu aceeași distanță",
  "offset.help": "Mărește sau micșorează corpul de-a lungul fețelor. Pentru jocul unei îmbinări prin presare: mărește-l și păstrează-l ca gaură.",
  "offset.direction": "Direcție",
