  "offset.distance": "Distanță",
  "offset.edges": "Colțuri exterioare",
  "offset.edgesHint": "Rotunjite păstrează suprafața decalată rotundă la colțurile exterioare; ascuțite lasă fețele să continue până se întâlnesc.",
  "offset.copy": "Păstrează originalul și adaugă corpul decalat ca gaură",
  "offset.sideways": "Doar lateral: fețele plate de sus și de jos rămân la înălțimea lor",
  "offset.apply": "Decalează",
  "offset.working": "Se decalează…",
  "offset.cancel": "Anulează decalarea",
  "offset.errorFailed": "Corpul nu a putut fi mărit sau micșorat cu această distanță. Alege o distanță mai mică.",
  "status.offsetGrown": "Mărit cu {size} mm",
  "status.offsetShrunk": "Micșorat cu {size} mm",
  "status.offsetCopy": "Corpul, decalat cu {size} mm, a fost adăugat ca gaură",
  "status.offsetMcp": "MCP a decalat obiectul cu {size} mm",
  "edge.revertOffset": "Decalare ({size} mm)",
  "historyStep.offsetOne": "Decalare {name}",
  "historyStep.offsetMany": "Decalare a {count} obiecte",
  "guide.edges.offset": "Decalarea mută fiecare față a unui corp cu aceeași distanță, în afară sau înăuntru. Mărește o copie și păstreaz-o ca gaură ca să obții jocul unei îmbinări prin presare, sau micșorează un corp pentru un știft care trebuie să intre într-o gaură. Corpurile care sunt doar un mesh de triunghiuri adesea nu pot fi decalate.",
  "edge.revertSurfaceTexture": "Textură de suprafață ({size} mm adâncime)",
  "deleteFace.title": "Șterge fața",
  "deleteFace.subtitle": "Fețele vecine închid golul",
  "deleteFace.help": "Dă clic pe fețele de șters; încă un clic scoate fața din nou. Fețele din jur cresc până se închide golul: o rotunjire, o gaură sau o proeminență dispare, iar corpul rămâne exact.",
  "deleteFace.preparing": "Se citesc fețele…",
  "deleteFace.countNone": "Nicio față aleasă încă",
  "deleteFace.countOne": "1 față aleasă",
  "deleteFace.countMany": "{count} fețe alese",
  "deleteFace.apply": "Șterge",
  "deleteFace.working": "Se șterg fețele…",
  "deleteFace.cancel": "Anulează ștergerea fețelor",
  "deleteFace.errorUnchanged": "Aceste fețe nu pot fi șterse: fețele din jurul lor nu închid golul. Alege toate fețele a ceea ce trebuie să dispară, cum ar fi toate fețele unei rotunjiri sau tot peretele unei găuri, și nicio față a corpului însuși.",
  "deleteFace.errorMesh": "Acest corp nu are fețe exacte de șters: Magic3D îl păstrează ca mesh, la fel ca un STL, OBJ sau 3MF importat, un corp împărțit, înfășurat sau simplificat, ori o formă foarte detaliată, cum ar fi un text lung. O piesă importată ca STEP are fețe exacte.",
  "deleteFace.errorResized": "Acest corp a fost redimensionat cu „Păstrează mărimea muchiilor la redimensionare” activat, așa că fețele lui exacte nu se mai potrivesc cu mărimea lui. Anulează redimensionarea, șterge fețele, apoi redimensionează-l din nou.",
  "deleteFace.errorProjectChanged": "Obiectul sau proiectul s-a schimbat în timp ce se ștergeau fețele; încearcă din nou.",
  "deleteFace.errorFailed": "Fețele nu au putut fi șterse. Alege alte fețe.",
  "deleteFace.errorNoFaces": "Fețele acestui corp nu au putut fi citite. Închide unealta și deschide-o din nou.",
  "deleteFace.errorTooSlow": "Ștergerea acestor fețe a durat prea mult și a fost oprită după 45 de secunde; nu s-a schimbat nimic. Nucleul CAD nu poate gestiona aceste fețe pe această piesă: alege alte fețe sau mai puține.",
  "status.facesDeletedOne": "1 față ștearsă",
  "status.facesDeletedMany": "{count} fețe șterse",
  "status.facesDeletedMcpOne": "MCP a șters 1 față",
  "status.facesDeletedMcpMany": "MCP a șters {count} fețe",
  "status.deleteFaceCancelled": "Ștergerea feței a fost anulată",
  "status.deleteFaceCancelledChanged": "Ștergerea feței a fost anulată pentru că obiectul s-a schimbat",
  "edge.revertDeleteFaceOne": "Fețe șterse (1 față)",
  "edge.revertDeleteFaceMany": "Fețe șterse ({count} fețe)",
