  "status.honeycombConverted": "Fagurele a fost transformat în model de găuri: {count}",
  "welcome.moreHolePatternTitle": "Model de găuri",
  "welcome.moreHolePatternBody": "Dă clic pe o față plană a unui corp și împrăștie găuri pe ea: rotunde, pătrate, dreptunghiulare, hexagonale sau fante, în grilă sau decalate, cu distanță între ele, margine până la muchie și adâncime (prin tot corpul sau o adâncime aleasă). O previzualizare îți arată găurile înainte să le creezi; ele rămân găuri obișnuite, grupate cu corpul - pentru aerisiri, grile de difuzor, coșuri și carcase.",
  "welcome.moreFaceTitle": "Împinge o față",
  "welcome.moreFaceBody": "trage în afară o față plană a unui corp sau taie un buzunar în ea, cu retragere față de muchie, colțuri rotunjite și adâncime, cu previzualizare - și pe STL-uri importate.",
  "welcome.moreTextureTitle": "Textură de suprafață",
  "welcome.moreTextureBody": "pune un relief pe orice corp, pentru aderență sau pentru aspect - moletare, caneluri, fagure, cărămizi, fibră de carbon, scoarță de copac, fibra lemnului, frânghie, o imagine ca hartă de înălțime sau text, în jurul corpurilor rotunde sau plat, de-a lungul unei axe.",
  "welcome.moreVaseTitle": "Vaze și ghivece",
  "welcome.moreVaseBody": "o formă dedicată pentru vaze, ghivece și abajururi: forma corpului, secțiunea, răsucirea, modele, găuri de scurgere, o farfurioară și un capac - plină pentru modul vază al slicerului sau goală.",
  "welcome.moreOffsetTitle": "Decalează și decupează",
  "welcome.moreOffsetBody": "crește sau micșorează un corp exact cu o distanță dată, de jur împrejur sau doar lateral, pentru jocul unei îmbinări presate, sau decupează o piesă din alta cu un spațiu de jur împrejur, într-un singur pas.",
  "guide.select.holePattern": "Model de găuri (butonul din bara de unelte de lângă Multiplicare, clic dreapta pe un corp sau Ctrl+K): dă clic pe o față plană, apoi setează forma găurii, mărimea, distanța, dispunerea, marginea și adâncimea. Găurile apar ca previzualizare; „Creează” le adaugă ca găuri grupate cu corpul. Degrupează le eliberează din nou.",
  "guide.select.faceTool": "Față (butonul din bara de unelte de lângă Model de găuri, clic dreapta pe un corp sau Ctrl+K): dă clic pe o față plană, alege În afară sau Înăuntru, apoi setează retragerea față de muchie, raza colțurilor și adâncimea. Ce se adaugă e un corp de schiță grupat cu corpul.",
  "scalePercent.errorTooSmall": "„{name}” ar deveni mai mic de 0,01 mm.",
  "scalePercent.errorTooLarge": "„{name}” ar deveni mai mare decât permite forma lui. Setează o „Limită de mărime personalizată” mai mare pentru ea la Valori implicite ale formelor, în setări, sau alege un procent mai mic.",
