  "status.meshTooDense": "Acest mesh are {triangles} triunghiuri. Prelucrarea muchiilor se descurcă cu {limit}; peste atât, nucleul durează mai mult decât merită orice așteptare. Pentru o formă din lista de forme, folosește deocamdată setările ei. Pentru o piesă importată, import-o ca STEP sau salveaz-o mai întâi cu mai puține triunghiuri.",
  "status.meshDenseAsk": "Acest mesh are {triangles} triunghiuri, mai mult decât cele {limit} pentru care e gândită prelucrarea muchiilor. Peste atât poate dura multe minute, pagina se poate bloca și tot ce n-ai salvat se pierde dacă trebuie s-o închizi. Salvează-ți mai întâi proiectul.\n\nÎncerci oricum?",
  "status.threadTooDense": "Un filet e construit din {triangles} triunghiuri — prea multe pentru prelucrarea muchiilor, care se oprește la {limit}. Așa că adaugă filetul după prelucrarea muchiilor: teșește sau rotunjește întâi corpul, apoi filetul. Teșitura capului din panoul de proprietăți rupe marginea capului șurubului fără acest ocol.",
