  "thread.flankAngleHint": "Unghiul dintre cele două flancuri ale unui dinte. 60° e filetul ascuțit în V, 30° filetul trapezoidal. La 90° sau mai puțin, niciun flanc nu e mai plat de 45°, așa că filetul se printează fără suporturi.",
