  "thread.axialClearanceHint": "Joc suplimentar de-a lungul filetului, în mm, peste jocul radial: fiecare dinte al piuliței devine mai subțire cu atât, iar diametrul rămâne. Pentru un filet care se învârte ușor fără să se clatine lateral: păstrează jocul pe la 0,2 – 0,3 și pune 0,2 aici. La 0, jocul vine doar din jocul radial, care deschide flancurile doar cam pe jumătate.",
  "thread.clearanceHint": "Spațiul suplimentar pe tot diametrul. Un filet printat are nevoie de mai mult decât ai crede: golul dintre flancuri e doar cam jumătate din el. Pe la 0,3 e strâns, 0,4 obișnuit, 0,5 larg. Printează mai întâi o pereche de probă.",
