  "gridfinity.tray": "Tavă",
  "gridfinity.trayHint": "O tavă de orice mărime în mm, cu fundul plat, pentru inserturi de jocuri de societate și piese mici: fără picioare și fără buză de stivuire, deci nu stă într-o placă de bază și nu se stivuiește. Separatoarele și polițele pentru etichete urcă până sus.",
