  "gridfinity.openingHint": "Adâncimea se măsoară de la vârful buzei (vârful cutiei, fără buză), iar distanța de la capătul de care e plasată deschiderea. Deschisă pe toată lățimea până la fund, latura e complet deschisă; o deschidere mai mică păstrează colțurile laturii și buza de lângă ea.",
