  "prop.gridfinityOpeningCornerSize": "Mărimea colțurilor deschiderii",
  "gridfinity.openingCornerHint": "Colțurile de sus și de jos ale deschiderilor, văzute din afara peretelui; sub 0,5 mm rămân drepte. O deschidere pe toată latura nu are colțuri sus.",
