  "gridfinity.paddingHint": "O bordură plină în afara grilei, ca placa de bază să umple un sertar care nu are un număr întreg de unități. Când schimbi adaosul, unitățile rămân, iar mărimea plăcii se schimbă odată cu el.",
  "prop.gridfinityCornerRadius": "Raza colțurilor",
  "gridfinity.cornerRadiusHint": "Raza celor patru colțuri exterioare ale plăcii: 4 mm, cum le desenează specificația Gridfinity, până la 0 pentru colțuri drepte care intră în colțurile sertarului. Locașurile își păstrează rotunjirea, deci cutiile se potrivesc ca înainte.",
  "gridfinity.binCornerRadiusHint": "Raza colțurilor exterioare ale cutiei, deasupra picioarelor: 3,75 mm, cum le desenează specificația Gridfinity, până la 0 pentru colțuri drepte, astfel încât cutiile alăturate într-un sertar să lase doar golurile de 0,5 mm acolo unde se întâlnesc patru. Picioarele, interiorul și pantele buzei pe care se sprijină o cutie stivuită își păstrează rotunjirea, deci cutia stă în placa de bază și se stivuiește ca înainte.",
